#!/usr/bin/env node
// Fetches ECB monthly-average FX rates from Frankfurter and (re)generates
// ops/fx_rates_seed.sql — a static, idempotent seed for the `fx_rates` table
// (structure in backend/migrations/006_fx_rates.sql).
//
// This intentionally does NOT touch Postgres directly and is NOT part of the
// backend/migrations/** auto-run chain (006's own comment: "loading the seed
// is tracked separately so a wrong guess never silently reaches price_eur").
// Apply the generated file explicitly once it's reviewed:
//   psql "$DATABASE_URL" -f ops/fx_rates_seed.sql
//
// Frankfurter returns EUR -> X; fx_rates.rate_to_eur is "1 unit of X = N EUR",
// so every rate is inverted after averaging. Only ECB business days are
// published (~20-22 per month) — average those, don't try to fill weekends.
//
// Usage: node ops/seed-fx-rates.mjs [startDate] [endDate]
//   Defaults span from the first date Frankfurter publishes (1999) is
//   overkill for this corpus, so we default to a fixed range wide enough to
//   safely predate the ~10-year purchase history without guessing its exact
//   start: 2014-01-01 through today.

import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const CURRENCIES = ['RON', 'CZK', 'PLN', 'HUF', 'SEK', 'DKK', 'NOK', 'GBP', 'USD', 'CHF'];

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OUT_PATH = path.join(__dirname, 'fx_rates_seed.sql');

function sqlStr(s) {
  return "'" + String(s).replace(/'/g, "''") + "'";
}

export async function fetchDailyRates(startDate, endDate) {
  const url = `https://api.frankfurter.dev/v1/${startDate}..${endDate}?base=EUR&symbols=${CURRENCIES.join(',')}`;
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error(`Frankfurter request failed: ${res.status} ${res.statusText}`);
  }
  const body = await res.json();
  return body.rates; // { "2015-01-02": { RON: 4.502, ... }, ... }
}

// Groups daily EUR->X rates by calendar month, averages, then inverts to
// "1 X = N EUR". Drops any month with fewer than MIN_DAYS observations — a
// boundary month from Frankfurter's date-snapping (e.g. a lone Dec 31 from a
// Jan 1 request) is not a real month's average.
export function monthlyRatesToEur(dailyRates, { minDays = 15 } = {}) {
  const byMonth = new Map(); // ym -> currency -> [rates]
  for (const [date, currencyMap] of Object.entries(dailyRates)) {
    const ym = date.slice(0, 7);
    if (!byMonth.has(ym)) byMonth.set(ym, new Map());
    const monthMap = byMonth.get(ym);
    for (const [currency, rate] of Object.entries(currencyMap)) {
      if (!monthMap.has(currency)) monthMap.set(currency, []);
      monthMap.get(currency).push(rate);
    }
  }

  const result = []; // { period: 'YYYY-MM-01', currency, rateToEur, days }
  for (const [ym, currencyMap] of byMonth) {
    for (const [currency, values] of currencyMap) {
      if (values.length < minDays) continue;
      const avgEurToX = values.reduce((a, b) => a + b, 0) / values.length;
      result.push({
        period: `${ym}-01`,
        currency,
        rateToEur: 1 / avgEurToX,
        days: values.length,
      });
    }
  }
  return result.sort((a, b) => a.period.localeCompare(b.period) || a.currency.localeCompare(b.currency));
}

export function toSql(rows) {
  const lines = [];
  lines.push('-- ops/fx_rates_seed.sql — generated by ops/seed-fx-rates.mjs from the');
  lines.push('-- Frankfurter (ECB) API. NOT part of the backend/migrations/** auto-run');
  lines.push('-- chain (see 006_fx_rates.sql\'s own comment) — apply explicitly:');
  lines.push('--   psql "$DATABASE_URL" -f ops/fx_rates_seed.sql');
  lines.push('--');
  lines.push('-- Frankfurter returns EUR -> X; rate_to_eur is "1 X = N EUR", so every');
  lines.push('-- rate here is inverted after averaging the month\'s published business days.');
  lines.push('-- Regenerate by re-running the script (safe: ON CONFLICT DO NOTHING, and');
  lines.push('-- past months\' published rates do not change).');
  lines.push('');
  lines.push('INSERT INTO fx_rates (currency, period, rate_to_eur, source) VALUES');
  const valueLines = rows.map(
    (r) => `  (${sqlStr(r.currency)}, ${sqlStr(r.period)}, ${r.rateToEur.toFixed(6)}, 'ecb')`
  );
  lines.push(valueLines.join(',\n'));
  lines.push('ON CONFLICT (currency, period) DO NOTHING;');
  return lines.join('\n') + '\n';
}

async function main() {
  const [, , startArg, endArg] = process.argv;
  const startDate = startArg || '2014-01-01';
  const endDate = endArg || new Date().toISOString().slice(0, 10);

  console.log(`[seed-fx-rates] fetching ${startDate}..${endDate} for ${CURRENCIES.join(', ')}`);
  const daily = await fetchDailyRates(startDate, endDate);
  const monthly = monthlyRatesToEur(daily);
  console.log(`[seed-fx-rates] ${Object.keys(daily).length} business days -> ${monthly.length} currency-months`);

  const sql = toSql(monthly);
  await writeFile(OUT_PATH, sql, 'utf8');
  console.log(`[seed-fx-rates] wrote ${OUT_PATH}`);
}

const isMain =
  process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1]);
if (isMain) {
  main().catch((err) => {
    console.error('[seed-fx-rates] failed:', err);
    process.exit(1);
  });
}
